import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Bot Access Control","description":"","frontmatter":{},"headers":[],"relativePath":"guides/access.md","filePath":"guides/access.md","lastUpdated":1790952322000}'),r={name:"guides/access.md"};function s(i,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="bot-access-control" tabindex="-1">Bot Access Control <a class="header-anchor" href="#bot-access-control" aria-label="Permalink to &quot;Bot Access Control&quot;">​</a></h1><p>Memoh access control has two layers:</p><ul><li><strong>Channel Members</strong> control identities coming from IM channels such as Telegram, Discord, Feishu, QQ, and similar platforms.</li><li><strong>Workspace Members</strong> control registered Memoh users in the app and workspace.</li></ul><p>The old ACL rule model still exists, but it is now the advanced engine behind Channel chat access. Most day-to-day changes should start from the bot&#39;s <strong>Access</strong> tab, using <strong>Channel Members</strong> and <strong>Workspace Members</strong>.</p><hr><h2 id="the-mental-model" tabindex="-1">The Mental Model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The Mental Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Identity</th><th>Controls</th></tr></thead><tbody><tr><td><strong>Channel Members</strong></td><td>A channel identity observed from an IM platform</td><td>Whether that platform identity can chat with the bot, and whether it can manage the bot from IM commands</td></tr><tr><td><strong>Workspace Members</strong></td><td>A registered Memoh user account</td><td>Whether that user can use the bot in the app, read/write files, run workspace commands, or manage bot settings</td></tr></tbody></table><p>These layers can be connected by account binding. A workspace user can bind a channel identity from <strong>Profile -&gt; Connected Accounts</strong> by generating a one-time code and sending <code>/link &lt;code&gt;</code> to a Memoh bot in IM. After binding, Memoh can tell that the IM identity belongs to that workspace user.</p><p>Binding does not grant access by itself. It only connects identities. Permissions still come from Channel Members, Workspace Members, bot ownership, or system admin status.</p><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="let-anyone-chat-from-im" tabindex="-1">Let Anyone Chat From IM <a class="header-anchor" href="#let-anyone-chat-from-im" aria-label="Permalink to &quot;Let Anyone Chat From IM&quot;">​</a></h3><ol><li>Open the bot&#39;s <strong>Access</strong> tab.</li><li>Go to <strong>Channel Members</strong>.</li><li>Set <strong>Access Mode</strong> to <strong>Blacklist Mode</strong>.</li><li>Leave the member list empty, or add only the identities you want to block.</li></ol><p>Blacklist Mode means the ACL default effect is <code>allow</code>. Everyone can chat unless a matching deny rule exists.</p><h3 id="allow-only-selected-im-identities" tabindex="-1">Allow Only Selected IM Identities <a class="header-anchor" href="#allow-only-selected-im-identities" aria-label="Permalink to &quot;Allow Only Selected IM Identities&quot;">​</a></h3><ol><li>Open <strong>Channel Members</strong>.</li><li>Set <strong>Access Mode</strong> to <strong>Whitelist Mode</strong>.</li><li>Add the channel identities that should be allowed.</li><li>Keep <strong>Chat</strong> checked for each allowed identity.</li></ol><p>Whitelist Mode means the ACL default effect is <code>deny</code>. Only matching allow rules can chat.</p><h3 id="give-a-web-user-access" tabindex="-1">Give A Web User Access <a class="header-anchor" href="#give-a-web-user-access" aria-label="Permalink to &quot;Give A Web User Access&quot;">​</a></h3><ol><li>Open <strong>Workspace Members</strong>.</li><li>Add a specific member, or add <strong>Everyone</strong>.</li><li>Select the permissions that member should have.</li></ol><p>Workspace access is for registered Memoh users. It is separate from IM chat access unless the user links their IM identity.</p><hr><h2 id="channel-members" tabindex="-1">Channel Members <a class="header-anchor" href="#channel-members" aria-label="Permalink to &quot;Channel Members&quot;">​</a></h2><p>Channel Members is the IM-side access surface.</p><p>Each row represents a <strong>channel identity</strong> — one Telegram user or Discord member — or a <strong>group</strong> (see below). Members are added from the inline picker in the card header; identity and group candidates appear in the same dropdown, grouped by section. A row can have two independent permissions:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Controls whether inbound IM messages from that identity can trigger the bot.</td></tr><tr><td><strong>Manage</strong></td><td>Controls whether that identity can manage the bot from IM slash commands. Manage does not automatically grant Chat.</td></tr></tbody></table><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>The Chat checkbox is backed by ACL rules for <code>chat.trigger</code>.</p><p>In <strong>Blacklist Mode</strong>:</p><ul><li>the default is <code>allow</code></li><li>adding or unchecking Chat for an identity creates a deny rule</li><li>checking Chat removes that identity-specific deny rule</li></ul><p>In <strong>Whitelist Mode</strong>:</p><ul><li>the default is <code>deny</code></li><li>adding or checking Chat for an identity creates an allow rule</li><li>unchecking Chat removes that identity-specific allow rule</li></ul><h3 id="manage" tabindex="-1">Manage <a class="header-anchor" href="#manage" aria-label="Permalink to &quot;Manage&quot;">​</a></h3><p>The Manage checkbox writes a local Channel Access override for that channel identity.</p><p>Manage is used by IM commands. It lets a channel identity act as a bot manager for owner-level slash command flows. It is intentionally independent from Chat: a manager can still be denied normal chat messages if Chat is off or the ACL denies them.</p><h3 id="groups-as-members" tabindex="-1">Groups As Members <a class="header-anchor" href="#groups-as-members" aria-label="Permalink to &quot;Groups As Members&quot;">​</a></h3><p>Besides individual identities, you can add an entire <strong>group chat</strong> as a member row. Group candidates come from conversations the bot has observed on its channels, and rows carry a &quot;Group&quot; badge.</p><ul><li>A group row&#39;s <strong>Chat</strong> checkbox means &quot;everyone in this group&quot; — in Whitelist Mode it allows the whole group to trigger the bot, in Blacklist Mode it blocks the whole group.</li><li><strong>Manage is not available for groups.</strong> Managers are always individual channel identities.</li><li>Rules that combine both — &quot;this person, in this group&quot; — are still possible through the advanced ACL rules.</li></ul><h3 id="platform-members" tabindex="-1">Platform Members <a class="header-anchor" href="#platform-members" aria-label="Permalink to &quot;Platform Members&quot;">​</a></h3><p>If a channel identity is linked to a workspace member of this bot, the row is marked as a platform member.</p><p>When the linked workspace member has <strong>Manage</strong> in Workspace Members, the channel identity inherits Manage automatically. The Channel Members row then shows that Manage is inherited. If you toggle Manage in Channel Members, Memoh writes a local override:</p><ul><li>local <strong>on</strong> forces Manage on for this channel identity</li><li>local <strong>off</strong> suppresses inherited Manage for this channel identity</li><li><strong>Reset to inherited</strong> removes the local override and follows Workspace Members again</li></ul><p>Only local-only channel rows can be removed from Channel Members. Platform member rows come from their workspace binding and are managed by permissions or by disconnecting the binding.</p><hr><h2 id="workspace-members" tabindex="-1">Workspace Members <a class="header-anchor" href="#workspace-members" aria-label="Permalink to &quot;Workspace Members&quot;">​</a></h2><p>Workspace Members is the web/workspace access surface.</p><p>You can grant access to:</p><ul><li>a <strong>specific member</strong></li><li><strong>Everyone</strong></li></ul><p>The bot owner is shown as an implicit owner entry and always has full access. System admins also resolve to full access.</p><p>Workspace permissions are:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Allows</th></tr></thead><tbody><tr><td><strong>Can chat</strong></td><td>Use the bot from web chat surfaces.</td></tr><tr><td><strong>Read files</strong></td><td>Read bot workspace files.</td></tr><tr><td><strong>Write files</strong></td><td>Modify bot workspace files. This also implies Read files.</td></tr><tr><td><strong>Run commands</strong></td><td>Run workspace execution flows.</td></tr><tr><td><strong>Can manage</strong></td><td>Manage bot settings and access. This implies all other workspace permissions.</td></tr></tbody></table><p>Workspace Manage also flows into Channel Members for linked channel identities. If a user with Workspace Manage links a Telegram identity, that Telegram identity inherits Manage on the channel side.</p><p>Workspace <strong>Can chat</strong> is not the same as Channel <strong>Chat</strong>. Workspace permissions authorize app and workspace APIs; Channel Chat authorizes IM inbound messages through the ACL engine.</p><hr><h2 id="linking-channel-identities" tabindex="-1">Linking Channel Identities <a class="header-anchor" href="#linking-channel-identities" aria-label="Permalink to &quot;Linking Channel Identities&quot;">​</a></h2><p>Users link IM identities from <strong>Profile -&gt; Connected Accounts</strong>:</p><ol><li>Click <strong>Connect</strong>.</li><li>Copy the generated <code>/link &lt;code&gt;</code> command.</li><li>Send it to a Memoh bot in an IM channel.</li><li>The code binds the sending channel identity to the current Memoh user account.</li></ol><p>Important details:</p><ul><li>link codes are one-time and expire after a short period</li><li><code>/link &lt;code&gt;</code> is allowed even when the sender is denied by chat ACL, so users can recover from an unlinked state</li><li>binding is account-level: it connects the workspace user and the channel identity globally</li><li>binding does not grant Chat or Manage by itself</li></ul><p>After linking, Workspace Manage can be inherited by the matching Channel Members row.</p><hr><h2 id="access-mode-and-advanced-acl-rules" tabindex="-1">Access Mode And Advanced ACL Rules <a class="header-anchor" href="#access-mode-and-advanced-acl-rules" aria-label="Permalink to &quot;Access Mode And Advanced ACL Rules&quot;">​</a></h2><p>Channel Chat uses the ACL engine. The Access page presents it as <strong>Access Mode</strong> plus optional advanced rules.</p><table tabindex="0"><thead><tr><th>Access Mode</th><th>ACL default effect</th><th>Matching rules that matter</th></tr></thead><tbody><tr><td><strong>Blacklist Mode</strong></td><td><code>allow</code></td><td><code>deny</code> rules</td></tr><tr><td><strong>Whitelist Mode</strong></td><td><code>deny</code></td><td><code>allow</code> rules</td></tr></tbody></table><p>Only rules opposite to the current default effect override the default mode. A rule with the same effect as the default does not change the result.</p><p>Advanced rules can target:</p><ul><li>all users</li><li>all users on a platform</li><li>one channel identity</li><li>one channel identity on a platform</li></ul><p>Advanced rules can also be scoped to:</p><ul><li>any chat</li><li>private conversations</li><li>group conversations</li><li>threads</li><li>a specific conversation ID</li><li>a specific thread ID</li></ul><p>The rule target handles platform filtering. Source scope handles conversation and thread filtering.</p><p>Unlike older ACL documentation, current versions do not expose manual rule priority or drag-to-reorder behavior. Think in terms of the current default mode plus matching opposite-effect rules.</p><hr><h2 id="creation-presets" tabindex="-1">Creation Presets <a class="header-anchor" href="#creation-presets" aria-label="Permalink to &quot;Creation Presets&quot;">​</a></h2><p>When creating a bot, the ACL preset only initializes Channel Chat behavior. You can change it later from <strong>Channel Members</strong>.</p><table tabindex="0"><thead><tr><th>Preset</th><th>Initial behavior</th></tr></thead><tbody><tr><td><code>allow_all</code></td><td>Default effect <code>allow</code>; no extra rules</td></tr><tr><td><code>private_only</code></td><td>Default effect <code>deny</code>; allow private conversations</td></tr><tr><td><code>group_only</code></td><td>Default effect <code>deny</code>; allow group conversations</td></tr><tr><td><code>group_and_thread_only</code></td><td>Default effect <code>deny</code>; allow group and thread conversations</td></tr><tr><td><code>deny_all</code></td><td>Default effect <code>deny</code>; no extra allow rules</td></tr></tbody></table><p>Presets do not configure Workspace Members and do not create account bindings.</p><hr><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="public-im-bot-with-a-few-blocks" tabindex="-1">Public IM Bot With A Few Blocks <a class="header-anchor" href="#public-im-bot-with-a-few-blocks" aria-label="Permalink to &quot;Public IM Bot With A Few Blocks&quot;">​</a></h3><p>Use <strong>Blacklist Mode</strong> in Channel Members. Leave Chat on by default and add blocked identities. Use Advanced rules only if you need to block an entire platform or a group/thread context.</p><h3 id="private-im-bot" tabindex="-1">Private IM Bot <a class="header-anchor" href="#private-im-bot" aria-label="Permalink to &quot;Private IM Bot&quot;">​</a></h3><p>Use <strong>Whitelist Mode</strong> in Channel Members. Add the allowed channel identities and keep Chat checked. If the same people should manage the bot from IM, also grant Manage.</p><h3 id="web-team-bot" tabindex="-1">Web Team Bot <a class="header-anchor" href="#web-team-bot" aria-label="Permalink to &quot;Web Team Bot&quot;">​</a></h3><p>Use <strong>Workspace Members</strong>. Add specific users or Everyone, then choose <code>Can chat</code>, file permissions, command execution, and Manage according to their web/workspace role.</p><h3 id="workspace-manager-also-manages-from-telegram" tabindex="-1">Workspace Manager Also Manages From Telegram <a class="header-anchor" href="#workspace-manager-also-manages-from-telegram" aria-label="Permalink to &quot;Workspace Manager Also Manages From Telegram&quot;">​</a></h3><p>Grant the user <strong>Can manage</strong> in Workspace Members. Ask them to link their Telegram account with <code>/link &lt;code&gt;</code>. Their Telegram identity will inherit Manage in Channel Members. If you need to disable Telegram-side management for that identity only, turn off Manage in Channel Members to create a local override.</p><hr><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h2><p>When access is surprising, check these in order:</p><ol><li><strong>Which layer is involved?</strong> IM messages use Channel Chat ACL. App and workspace APIs use Workspace Members.</li><li><strong>Is the identity linked?</strong> Connected Accounts determines whether Workspace Manage can inherit into Channel Members.</li><li><strong>What is the Channel Access Mode?</strong> Blacklist Mode defaults to allow; Whitelist Mode defaults to deny.</li><li><strong>Is Manage inherited or overridden?</strong> The Channel Members info popover shows whether Manage follows Workspace Members or is locally overridden.</li><li><strong>What does <code>/access</code> show?</strong> In IM, <code>/access</code> reports the current identity, write access, and chat ACL context for the sender.</li></ol><p>Remember that Manage and Chat are separate. Manage can allow owner-level IM commands, but normal inbound chat still needs Channel Chat to allow the sender.</p>',90)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
